package com.example.waktusolatmalaysia;
import static org.junit.Assert.*;import android.appwidget.*;import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import com.example.waktusolatmalaysia.widgets.*;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Separate invocations on either side of a real emulator reboot. */
@RunWith(AndroidJUnit4.class) public class WidgetLifecycleV32Test {
 @Test public void boundComponentsSurviveActualReboot()throws Exception{
  String stage=InstrumentationRegistry.getArguments().getString("lifecycle","");org.junit.Assume.assumeTrue(stage.equals("before")||stage.equals("after"));Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();AppWidgetManager manager=AppWidgetManager.getInstance(c);AppWidgetHost host=new AppWidgetHost(c,32013);File fixture=new File(c.getFilesDir(),"widget-reboot-fixture.json");
  if(stage.equals("before")){JSONArray ids=new JSONArray();for(WidgetProviderDescriptor d:WidgetProviderDescriptor.ALL){int id=host.allocateAppWidgetId();ids.put(id);assertTrue(manager.bindAppWidgetIdIfAllowed(id,new ComponentName(c,d.component)));new WidgetConfigV2(new JSONObject().put("schemaVersion",2).put("followApp",false).put("zone","WLY01").put("theme","dark"),d).save(c,id);PrayerWidgets.update(c,id,d);}try(FileOutputStream out=new FileOutputStream(fixture)){out.write(ids.toString().getBytes(StandardCharsets.UTF_8));}}
  else{try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(FileInputStream in=new FileInputStream(fixture)){byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}JSONArray ids=new JSONArray(out.toString("UTF-8"));int n=0;for(WidgetProviderDescriptor d:WidgetProviderDescriptor.ALL){int id=ids.getInt(n++);assertSame(d,WidgetProviderDescriptor.instance(c,id));WidgetConfigV2 cfg=WidgetConfigV2.read(c,id,d);assertEquals("dark",cfg.theme);assertFalse(cfg.followApp);assertEquals("WLY01",cfg.resolvedZone(c).code);PrayerWidgets.update(c,id,d);}assertEquals(4,ids.length());}finally{host.deleteHost();fixture.delete();}}
 }
}
